<td><code v-pre>'light'|'dark'</code></td>
<td><code v-pre>'light'</code></td>
</tr>
<tr>
<td>mode</td>
<td>菜单的模式</td>
<td><code v-pre>'vertical'|'horizontal'|'pop'|'popButton'</code></td>
<td><code v-pre>'vertical'</code></td>
</tr>
<tr>
<td>level-indent</td>
<td>层级之间的缩进</td>
<td><code v-pre>number</code></td>
<td><code v-pre>-</code></td>
</tr>
<tr>
<td>auto-open</td>
<td>默认展开所有多级菜单</td>
<td><code v-pre>boolean</code></td>
<td><code v-pre>false</code></td>
</tr>
<tr>
<td>collapsed(<strong>v-model</strong>)</td>
<td>是否折叠菜单</td>
<td><code v-pre>boolean</code></td>
<td><code v-pre>-</code></td>
</tr>
<tr>
<td>default-collapsed</td>
<td>默认是否折叠菜单</td>
<td><code v-pre>boolean</code></td>
<td><code v-pre>false</code></td>
</tr>
<tr>
<td>collapsed-width</td>
<td>折叠菜单宽度</td>
<td><code v-pre>number</code></td>
<td><code v-pre>-</code></td>
</tr>
<tr>
<td>accordion</td>
<td>开启手风琴模式</td>
<td><code v-pre>boolean</code></td>
<td><code v-pre>false</code></td>
</tr>
<tr>
<td>auto-scroll-into-view</td>
<td>是否自动滚动选中项目到可视区域</td>
<td><code v-pre>boolean</code></td>
<td><code v-pre>false</code></td>
</tr>
<tr>
<td>show-collapse-button</td>
<td>是否显示折叠按钮</td>
<td><code v-pre>boolean</code></td>
<td><code v-pre>false</code></td>
</tr>
<tr>
<td>selected-keys(<strong>v-model</strong>)</td>
<td>展开的菜单项key数组</td>
<td><code v-pre>string[]</code></td>
<td><code v-pre>-</code></td>
</tr>
<tr>
<td>default-selected-keys</td>
<td>默认选中的菜单项key数组</td>
<td><code v-pre>string[]</code></td>
<td><code v-pre>[]</code></td>
</tr>
<tr>
<td>open-keys(<strong>v-model</strong>)</td>
<td>展开的子菜单项key数组</td>
<td><code v-pre>string[]</code></td>
<td><code v-pre>-</code></td>
</tr>
<tr>
<td>default-open-keys</td>
<td>默认展开的子菜单项key数组</td>
<td><code v-pre>string[]</code></td>
<td><code v-pre>[]</code></td>
</tr>
<tr>
<td>scroll-config</td>
<td>滚动到可见区域的配置项，接收所有<code v-pre>scroll-into-view-if-needed</code>的参数</td>
<td><code v-pre>{[key :string]: any}</code></td>
<td><code v-pre>-</code></td>
</tr>
<tr>
<td>trigger-props</td>
<td>弹出模式下可接受所有<code v-pre>Trigger</code>的<code v-pre>props</code></td>
<td><code v-pre>TriggerProps</code></td>
<td><code v-pre>-</code></td>
</tr>
<tr>
<td>tooltip-props</td>
<td>弹出模式下可接受所有<code v-pre>Tooltip</code>的<code v-pre>props</code></td>
<td><code v-pre>object</code></td>
<td><code v-pre>-</code></td>
</tr>
<tr>
<td>auto-open-selected</td>
<td>默认选中的菜单</td>
<td><code v-pre>boolean</code></td>
<td><code v-pre>false</code></td>
</tr>
<tr>
<td>breakpoint</td>
<td>响应式收缩的断点</td>
<td><code v-pre>'xxl'|'xl'|'lg'|'md'|'sm'|'x'|'s'</code></td>
<td><code v-pre>-</code></td>
</tr>
<tr>
<td>popup-max-height</td>
<td>弹出模式下的最大高度</td>
<td><code v-pre>boolean| number</code></td>
<td><code v-pre>true</code></td>
</tr>
